  function enlaceWhatsAppFamiliaApp(telefono?: string | null) {
    let numero = String(telefono || '').replace(/\D/g, '');
    if (!numero) return '';
    if (numero.startsWith('00')) numero = numero.slice(2);
    if (numero.length === 9) numero = `34${numero}`;
    return `https://wa.me/${numero}`;
  }

