                        const fecha = new Date(`${valor}T12:00:00`);
                        const diaSemana = fecha.getDay();
                        const desplazamiento =
                          diaSemana === 0 ? -6 : 1 - diaSemana;
                        fecha.setDate(fecha.getDate() + desplazamiento);
                        setSnowZoneSemanaInicio(fechaIsoEditor(fecha));
